  "11-3": {
    slides: [
      { type: "title", stage: "Unit 11 · Lesson 3", eyebrow: "A1 · Ignite", title: "Messages and Communication", subtitle: "Use simple communication phrases online." },
      { type: "dialogue", stage: "Warm-Up", heading: "Quick Question", subheading: "Getting started", turns: [{ who: "teacher", text: "How do you start a message to a friend?" }, { who: "student", text: "I say ___." }], instruction: [["👂", "Listen to the question,"], ["🗣️", "then answer."]] },
      { type: "vocab", stage: "Getting Ready", heading: "Message Phrases", subheading: "Start, ask, request, finish", items: [{ label: "Hi! How are you?" }, { label: "Are you free?" }, { label: "Can you send me...?" }, { label: "See you later!" }], instruction: [["👀", "Look at the four phrases,"], ["🗣️", "and say each one aloud."]] },
      { type: "examples", stage: "Learn It", heading: "Complete the Message", subheading: "Fill in the missing words", rows: [["Hi! ___ are you?", "Hi! How are you?"], ["Can you ___ me the photo?", "Can you send me the photo?"]], instruction: [["👂", "Listen to each message,"], ["🗣️", "then repeat it."]] },
      { type: "dialogue", stage: "Try It", heading: "Choose a Phrase", subheading: "Match the situation to a phrase", turns: [{ who: "teacher", text: "You want a photo. What do you say?" }, { who: "student", text: "Can you send me the photo?" }], instruction: [["🗣️", "Choose the right phrase."]] },
      { type: "dialogue", stage: "Try It Again", heading: "One More Round", subheading: "Same idea, new situation", turns: [{ who: "teacher", text: "You want to end the chat. What do you say?" }, { who: "student", text: "See you later!" }], instruction: [["🗣️", "Choose the right phrase."]] },
      { type: "wheel", stage: "Message Mission", heading: "Spin & Respond", items: [{ label: "Starting a chat" }, { label: "Asking if they're free" }, { label: "Requesting a photo" }, { label: "Ending a chat" }], instruction: [["🎡", "Spin the wheel,"], ["🗣️", "then say the right phrase."]] },
      { type: "spoterror", stage: "Spot the Error", heading: "Which One Is Right?", rounds: [{ a: "Can you send me the photo.", b: "Can you send me the photo?", wrongSide: "a", fix: "Can you send me the photo?", explain: "A request phrased as a question needs a question mark at the end." }, { a: "You free?", b: "Are you free?", wrongSide: "a", fix: "Are you free?", explain: "A yes/no question needs are at the start, not just a statement with a question mark." }], instruction: [["🤔", "Say which one has the mistake,"], ["🗣️", "then say the fix out loud."]] },
      { type: "orderup", stage: "Put the Chat in Order", heading: "Put the Chat in Order!", prompt: "Tap the lines in the order they'd really happen.", items: ["Hi! How are you?", "I'm good, thanks!", "Can you send me the photo?", "Sure, one second!"], instruction: [["🤔", "Think about the order of the chat,"], ["👆", "then tap each line to place it."]] },
      { type: "speed", stage: "Message Phrase Speed Round", heading: "Message Phrase Speed Round!", seconds: 40, question: "Say the right message phrase for each situation, as fast as you can.", sample: "Starting a chat → Hi! How are you?", items: ["Starting a chat", "Asking if they're free", "Requesting a photo", "Ending a chat", "Asking what they're doing", "Saying goodbye"], instruction: [["🗣️", "Say the right phrase for each situation,"], ["⏱️", "as fast as you can."]] },
      { type: "practice", stage: "Exit Check", heading: "Four Phrases", subheading: "A greeting, a question, a request, a closing", line: "___! ___? Can you ___? ___!", instruction: [["🗣️", "Say all four phrases,"], ["🙅", "without any help this time."]] },
      { type: "landing", stage: "Wrap-Up", heading: "Nice Work!", caption: "You can now use simple message phrases online. Next up: tech questions." },
    ],
  },
