  "11-5": {
    slides: [
      { type: "title", stage: "Unit 11 · Unit Review", eyebrow: "A1 · Ignite", title: "Unit Review", subtitle: "Talk briefly about technology and online habits. No new language today." },
      { type: "vocab", stage: "Quick Tech Round", heading: "Rapid-Fire Review", subheading: "Phone use, online activities, apps", items: [{ label: "What do you use your phone for?" }, { label: "What do you do online?" }, { label: "What app do you use?" }], instruction: [["👀", "Look and recall,"], ["🗣️", "then answer fast."]] },
      { type: "message", stage: "Build a Digital Life Profile", heading: "Choose", subheading: "Devices, apps, activities, communication habits", lines: ["I use a *phone and a laptop*.", "I *watch videos* online and *message my friends*."], instruction: [["👂", "Listen,"], ["🗣️", "then build your own profile."]] },
      { type: "dialogue", stage: "Controlled Practice", heading: "Situation Change", subheading: "Adapt when the situation changes", turns: [{ who: "teacher", text: "You don't have your phone today. What do you do?" }, { who: "student", text: "I use my laptop instead." }, { who: "teacher", text: "You have only 30 minutes online. What do you choose?" }], instruction: [["🗣️", "Adapt your answer."]] },
      { type: "dialogue", stage: "Controlled Practice 2", heading: "My Digital Life Challenge", subheading: "45-60 seconds about your digital life, then 4 follow-up questions", turns: [{ who: "student", text: "I use a phone and a laptop. I watch videos online. I message my friends. I use my laptop for school." }, { who: "teacher", text: "Do you like using technology? What app do you use most?" }], instruction: [["🗣️", "Speak for 45-60 seconds."]] },
      { type: "factorcap", stage: "Tech Fact Check", heading: "Fact or Cap?", statements: [{ text: "A tablet is bigger than a phone.", isTrue: true, explain: "Right, a tablet has a larger screen than a phone." }, { text: "You use headphones to see photos.", isTrue: false, explain: "Headphones are for listening, not seeing. You'd use your eyes or a screen." }, { text: "Messaging friends is an online activity.", isTrue: true, explain: "Exactly, sending messages needs an internet connection." }, { text: "You can't watch videos on a laptop.", isTrue: false, explain: "You can watch videos on a laptop, phone, or tablet." }], instruction: [["🤔", "Decide whether it's a fact or a cap."]] },
      { type: "mystery", stage: "Cast Mystery", heading: "Guess the Classmate", question: "Ivy loves music apps. Samuel uses his laptop every day. Rin studies online. Carlos messages friends a lot.", clues: ["This person studies online.", "This person is a girl.", "Their name starts with R."], answer: "Rin", instruction: [["🗣️", "Ask your teacher for a clue,"], ["🤔", "then guess the classmate."]] },
      { type: "thisorthat", stage: "Online or Offline", heading: "This or That", pairs: [["Watch videos", "Read a book"], ["Message a friend", "Talk in person"], ["Study online", "Study with a book"]], instruction: [["🗣️", "Choose one,"], ["🗣️", "then say why."]] },
      { type: "thisorthat", stage: "Online or Offline 2", heading: "This or That Again", pairs: [["Play games online", "Play outside"], ["Send a message", "Call on the phone"], ["Watch on a tablet", "Watch on a laptop"]], instruction: [["🗣️", "Choose one,"], ["🗣️", "then say why."]] },
      { type: "practice", stage: "Exit Check", heading: "Quick Tech Round", subheading: "Phone use, online activity, favorite app, opinion", line: "I use my phone for ___. Online, I ___. My favorite app is ___.", instruction: [["🗣️", "Answer independently,"], ["🙅", "without any help this time."]] },
      { type: "landing", stage: "Unit Complete!", heading: "Unit 11 Complete!", caption: "You can name tech words, talk about your online habits, message someone, and answer tech questions." },
    ],
  },
