  "12-3": {
    slides: [
      { type: "title", stage: "Unit 12 · Lesson 3", eyebrow: "A1 · Ignite", title: "Invitations and Responses", subtitle: "Make and answer a simple invitation." },
      { type: "dialogue", stage: "Warm-Up", heading: "Quick Question", subheading: "Getting started", turns: [{ who: "teacher", text: "Do you want to be friends?" }, { who: "student", text: "Sure! / Yes, I'd love to." }], instruction: [["👂", "Listen to the question,"], ["🗣️", "then answer."]] },
      { type: "vocab", stage: "Getting Ready", heading: "Invite & Respond", subheading: "New phrases for this unit", items: [{ label: "Do you want to...?" }, { label: "Let's..." }, { label: "Sure! / Yes, I'd love to." }, { label: "Sorry, I can't." }], instruction: [["👀", "Look at the four phrases,"], ["🗣️", "and say each one aloud."]] },
      { type: "examples", stage: "Learn It", heading: "Accept or Refuse", subheading: "Choose a response, then say it fully", rows: [["Do you want to watch a movie?", "Sure!"], ["Do you want to play basketball?", "Sorry, I can't."]], instruction: [["👂", "Listen to each response,"], ["🗣️", "then repeat it."]] },
      { type: "dialogue", stage: "Try It", heading: "Good Response?", subheading: "Accept politely or refuse politely", turns: [{ who: "teacher", text: "Do you want to go shopping?" }, { who: "student", text: "Yes, I'd love to." }], instruction: [["🗣️", "Accept politely,"], ["🗣️", "or refuse politely."]] },
      { type: "dialogue", stage: "Try It Again", heading: "One More Round", subheading: "Same idea, new invitation", turns: [{ who: "teacher", text: "Do you want to visit my family?" }, { who: "student", text: "Sorry, I can't." }], instruction: [["🗣️", "Accept politely,"], ["🗣️", "or refuse politely."]] },
      { type: "wheel", stage: "Weekend Invitation Mission", heading: "Spin & Invite", items: [{ label: "Watch a movie" }, { label: "Play basketball" }, { label: "Go shopping" }, { label: "Hang out at home" }], instruction: [["🎡", "Spin the wheel,"], ["🗣️", "then invite, accept, or refuse."]] },
      { type: "spoterror", stage: "Spot the Error", heading: "Which One Is Right?", rounds: [{ a: "You want to watch a movie?", b: "Do you want to watch a movie?", wrongSide: "a", fix: "Do you want to watch a movie?", explain: "A yes/no question needs do at the start, not just a statement with a question mark." }, { a: "Sorry, I can.", b: "Sorry, I can't.", wrongSide: "a", fix: "Sorry, I can't.", explain: "A polite refusal needs the negative can't, not can." }], instruction: [["🤔", "Say which one has the mistake,"], ["🗣️", "then say the fix out loud."]] },
      { type: "orderup", stage: "Put the Invitation in Order", heading: "Put the Invitation in Order!", prompt: "Tap the lines in the order they'd really happen.", items: ["Do you want to watch a movie?", "Sure, I'd love to!", "What time?", "How about Saturday at 4?"], instruction: [["🤔", "Think about the order of the invitation,"], ["👆", "then tap each line to place it."]] },
      { type: "speed", stage: "Invitation Speed Round", heading: "Invitation Speed Round!", seconds: 40, question: "Make an invitation for each activity, then accept or refuse, as fast as you can.", sample: "Shopping → Do you want to go shopping? Sure, I'd love to!", items: ["Shopping", "Movie", "Basketball", "Hanging out", "Studying", "Visiting family"], instruction: [["🗣️", "Invite, then respond to each activity,"], ["⏱️", "as fast as you can."]] },
      { type: "practice", stage: "Exit Check", heading: "Invite, Accept, Refuse", subheading: "One invitation, one acceptance, one polite refusal", line: "Do you want to ___? Sure! / Sorry, I can't.", instruction: [["🗣️", "Invite, accept, and refuse,"], ["🙅", "without any help this time."]] },
      { type: "landing", stage: "Wrap-Up", heading: "Nice Work!", caption: "You can now make and answer invitations. Next up: talking about the weekend." },
    ],
  },
